self.addEventListener("push",t=>{let i;if(t.data){try{i=t.data.json()}catch(n){i={title:"OliveIQ",body:t.data.text()}}t.waitUntil(self.registration.showNotification(i.title||"OliveIQ",{body:i.body||"",icon:"/icons/icon-192.png",badge:"/icons/icon-192.png",tag:i.tag||"oliveiq",data:{url:i.url||"/dashboard"}}))}}),self.addEventListener("notificationclick",t=>{t.notification.close();let i=t.notification.data&&t.notification.data.url||"/dashboard";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let n of t)if("focus"in n){n.focus(),"navigate"in n&&n.navigate(i);return}return self.clients.openWindow(i)}))});